#' Cluster Analysis Gerarchica
#'
#' 
#' @param data .
#' @param vars Variabili su cui calcolare la matrice delle distanze e
#'   applicare l'algoritmo di clustering gerarchico. Sono ammesse variabili
#'   quantitative e categoriali: Gower è la metrica adatta ai dataset misti,
#'   Sokal-Michener e Jaccard (politomici) trattano le modalità come categorie,
#'   mentre Euclidea, Manhattan e Mahalanobis trattano i valori come quantità
#'   (ammesse anche su categoriali con modalità numeriche, ma i codici entrano
#'   nel calcolo come numeri).
#' @param asimm Variabili binarie di presenza/assenza (0 = assenza, 1 =
#'   presenza), che entrano nella base della segmentazione insieme a quelle di
#'   \code{vars}. Con la distanza di Gower la co-assenza (0 in entrambe le
#'   unità) non entra nel confronto: per quella coppia la variabile esce dalla
#'   media, come nell'indice di Jaccard. Una variabile a due modalità entrambe
#'   informative (per esempio il sesso) va invece in \code{vars}. Con le altre
#'   distanze queste variabili sono trattate come quelle di \code{vars}.
#' @param tuto Se TRUE mostra il pannello con la descrizione metodologica
#'   dell'analisi.
#' @param dis Metrica di distanza fra osservazioni. In tutte le metriche di
#'   matching il valore 0 significa "assenza", sia che la variabile sia numerica
#'   sia che sia un fattore con livelli numerici.
#'   'euclidean'/'manhattan'/'mahalanobis' trattano i valori come quantità (una
#'   variabile categoriale con modalità numeriche è ammessa, ma i codici entrano
#'   nel calcolo come numeri); 'binary' (Jaccard) richiede variabili a due
#'   modalità codificate 0/1; 'SokalMichener' è il simple matching, valido anche
#'   con più modalità; 'politomici' è il Jaccard per variabili categoriali con
#'   più modalità; 'gower' è l'unica metrica adatta ai dataset MISTI
#'   quantitativi + qualitativi (normalizza ogni variabile quantitativa per il
#'   proprio range, usa il simple matching per quelle categoriali ed esclude la
#'   co-assenza per le binarie di presenza/assenza di \code{asimm}; la
#'   standardizzazione esplicita non ha effetto perché già inclusa nella
#'   definizione).
#' @param method Criterio di agglomerazione passato a stats::hclust. Ward
#'   (ward.D2) è la scelta più comune per dati quantitativi standardizzati.
#' @param stdVars Se TRUE standardizza le variabili prima del calcolo della
#'   distanza. Applicato solo a distanze numeriche (Euclidea, Manhattan,
#'   Mahalanobis); ignorato per distanze binarie/categoriche.
#' @param n_clusters Numero di cluster k a cui tagliare il dendrogramma per
#'   produrre l'assegnazione delle osservazioni.
#' @param outputName Nome della colonna che jamovi inietterà nel dataset con
#'   l'assegnazione di ciascuna osservazione al proprio cluster.
#' @param dend Se TRUE produce il dendrogramma colorato per cluster.
#' @param r2 Se TRUE produce il grafico dell'R² al variare di k.
#' @param rmsstd Se TRUE produce il grafico dell'RMSSTD al variare di k.
#' @param deltaG Se TRUE produce il grafico del Delta G (differenza fra
#'   altezze di unione successive) al variare di k.
#' @param ch_index Se TRUE produce il grafico dell'Indice F di
#'   Calinski-Harabasz al variare di k.
#' @param width_dend .
#' @param height_dend .
#' @param width_r2 .
#' @param height_r2 .
#' @param width_rmsstd .
#' @param height_rmsstd .
#' @param width_deltaG .
#' @param height_deltaG .
#' @param width_ch .
#' @param height_ch .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$instructions} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$izpis} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$metriche} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$groups} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$label_cluster} \tab \tab \tab \tab \tab an output \cr
#'   \code{results$plot_dend} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$plot_r2} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$plot_rmsstd} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$plot_deltaG} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$plot_ch_index} \tab \tab \tab \tab \tab an image \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$izpis$asDF}
#'
#' \code{as.data.frame(results$izpis)}
#'
#' @export
hc <- function(
    data,
    vars,
    asimm = list(),
    tuto = TRUE,
    dis = "euclidean",
    method = "ward.D2",
    stdVars = TRUE,
    n_clusters = 2,
    outputName = "Cluster",
    dend = FALSE,
    r2 = FALSE,
    rmsstd = FALSE,
    deltaG = FALSE,
    ch_index = FALSE,
    width_dend = 500,
    height_dend = 500,
    width_r2 = 500,
    height_r2 = 500,
    width_rmsstd = 500,
    height_rmsstd = 500,
    width_deltaG = 500,
    height_deltaG = 500,
    width_ch = 500,
    height_ch = 500) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("hc requires jmvcore to be installed (restart may be required)")

    if ( ! missing(vars)) vars <- jmvcore::resolveQuo(jmvcore::enquo(vars))
    if ( ! missing(asimm)) asimm <- jmvcore::resolveQuo(jmvcore::enquo(asimm))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(vars), vars, NULL),
            `if`( ! missing(asimm), asimm, NULL))


    options <- hcOptions$new(
        vars = vars,
        asimm = asimm,
        tuto = tuto,
        dis = dis,
        method = method,
        stdVars = stdVars,
        n_clusters = n_clusters,
        outputName = outputName,
        dend = dend,
        r2 = r2,
        rmsstd = rmsstd,
        deltaG = deltaG,
        ch_index = ch_index,
        width_dend = width_dend,
        height_dend = height_dend,
        width_r2 = width_r2,
        height_r2 = height_r2,
        width_rmsstd = width_rmsstd,
        height_rmsstd = height_rmsstd,
        width_deltaG = width_deltaG,
        height_deltaG = height_deltaG,
        width_ch = width_ch,
        height_ch = height_ch)

    analysis <- hcClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

